const xhr = new XMLHttpRequest();
xhr.open('GET', '/api/productos');

xhr.onload = function () {
  if (xhr.status === 200) {
    const lista = JSON.parse(xhr.responseText);
    mostrar(lista);
  }
};
xhr.onerror = function () {
  console.error('Error de red');
};

xhr.send();

